# ---- FLOW-RTRIP-5: sh:order per declared predicate, equal to its DDL column
# index (schema.ts; 0 = id, never materialized here — gaps are geometry/id).
# The ClassSpec/PredicateSpec format has no order slot (contract.rs has no
# `order` field on PredicateSpec; shacl_emit.rs never emits sh:order), so it
# is carried here per this unit's brief.
fsh:SystemOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:System ;
  sh:property [ sh:path flow:parent ; sh:order 1 ] ;
  sh:property [ sh:path flow:name ; sh:order 2 ] ;
  sh:property [ sh:path flow:description ; sh:order 3 ] ;
  sh:property [ sh:path flow:displayMode ; sh:order 4 ] ;
  sh:property [ sh:path flow:color ; sh:order 5 ] .
fsh:RequirementOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Requirement ;
  sh:property [ sh:path flow:ownedBy ; sh:order 1 ] ;
  sh:property [ sh:path flow:text ; sh:order 2 ] ;
  sh:property [ sh:path flow:requirementSource ; sh:order 3 ] ;
  sh:property [ sh:path flow:status ; sh:order 4 ] ;
  sh:property [ sh:path flow:sortOrder ; sh:order 5 ] ;
  sh:property [ sh:path flow:startDate ; sh:order 6 ] ;
  sh:property [ sh:path flow:dueDate ; sh:order 7 ] ;
  sh:property [ sh:path flow:durationDays ; sh:order 8 ] .
fsh:TaskOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Task ;
  sh:property [ sh:path flow:ownerType ; sh:order 1 ] ;
  sh:property [ sh:path flow:ownedBy ; sh:order 2 ] ;
  sh:property [ sh:path flow:text ; sh:order 3 ] ;
  sh:property [ sh:path flow:done ; sh:order 4 ] ;
  sh:property [ sh:path flow:sortOrder ; sh:order 5 ] ;
  sh:property [ sh:path flow:startDate ; sh:order 6 ] ;
  sh:property [ sh:path flow:dueDate ; sh:order 7 ] ;
  sh:property [ sh:path flow:durationDays ; sh:order 8 ] .
fsh:WorkflowOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Workflow ;
  sh:property [ sh:path flow:name ; sh:order 1 ] ;
  sh:property [ sh:path flow:description ; sh:order 2 ] .
fsh:OutcomeOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Outcome ;
  sh:property [ sh:path flow:workflow ; sh:order 1 ] ;
  sh:property [ sh:path flow:text ; sh:order 2 ] ;
  sh:property [ sh:path flow:achieved ; sh:order 3 ] ;
  sh:property [ sh:path flow:sortOrder ; sh:order 4 ] .
fsh:WorkflowLinkOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:WorkflowLink ;
  sh:property [ sh:path flow:workflow ; sh:order 1 ] ;
  sh:property [ sh:path flow:system ; sh:order 2 ] ;
  sh:property [ sh:path flow:role ; sh:order 3 ] .
fsh:TradeOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Trade ;
  sh:property [ sh:path flow:name ; sh:order 1 ] ;
  sh:property [ sh:path flow:tradeRationale ; sh:order 2 ] ;
  sh:property [ sh:path flow:winner ; sh:order 3 ] .
fsh:TradeLinkOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:TradeLink ;
  sh:property [ sh:path flow:trade ; sh:order 1 ] ;
  sh:property [ sh:path flow:system ; sh:order 2 ] .
fsh:ConstraintOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Constraint ;
  sh:property [ sh:path flow:name ; sh:order 1 ] ;
  sh:property [ sh:path flow:description ; sh:order 2 ] .
fsh:ConstraintLinkOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:ConstraintLink ;
  sh:property [ sh:path flow:constraint ; sh:order 1 ] ;
  sh:property [ sh:path flow:target ; sh:order 2 ] ;
  sh:property [ sh:path flow:note ; sh:order 3 ] .
fsh:SourceOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Source ;
  sh:property [ sh:path flow:ownedBy ; sh:order 1 ] ;
  sh:property [ sh:path flow:sourceCitation ; sh:order 2 ] ;
  sh:property [ sh:path flow:sortOrder ; sh:order 3 ] .
fsh:EdgeOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Edge ;
  sh:property [ sh:path flow:sourceNode ; sh:order 1 ] ;
  sh:property [ sh:path flow:targetNode ; sh:order 2 ] ;
  sh:property [ sh:path flow:label ; sh:order 3 ] .
fsh:DependencyOrderShape a sh:NodeShape ; sh:severity sh:Info ; sh:targetClass flow:Dependency ;
  sh:property [ sh:path flow:predecessor ; sh:order 1 ] ;
  sh:property [ sh:path flow:successor ; sh:order 2 ] .

# ---- enums (sh:in), closed vocabularies read from types.ts
#
# sh:severity placement, IMPORTANT: rudof does NOT cascade a NodeShape's
# sh:severity down into its nested `sh:property [...]` blank-node shapes —
# each (property-)shape has its OWN severity, independently defaulting to
# sh:Violation. Measured directly: an outer-only `sh:severity sh:Warning`
# on fsh:SystemColorShape still reported severity Violation on the
# flow:color pattern result. Every sh:severity below therefore sits on the
# sh:property block itself (the SAME discipline this file already applies
# to sh:sparql: shacl_sparql.rs reads `?c sh:severity ?sev` off the
# constraint node, not the enclosing shape).
fsh:SystemDisplayModeShape a sh:NodeShape ; sh:targetClass flow:System ;
  sh:property [ sh:path flow:displayMode ; sh:in ( "solid" "outline" ) ; sh:severity sh:Violation ] .
fsh:RequirementStatusShape a sh:NodeShape ; sh:targetClass flow:Requirement ;
  sh:property [ sh:path flow:status ; sh:in ( "open" "met" "waived" ) ; sh:severity sh:Violation ] .
fsh:TaskOwnerTypeShape a sh:NodeShape ; sh:targetClass flow:Task ;
  sh:property [ sh:path flow:ownerType ; sh:in ( "system" "workflow" ) ; sh:severity sh:Violation ] .

# ---- patterns and tolerated-but-flagged rules (severity Warning mirrors
# flow-shapes-v1.ttl exactly: the app itself only tolerates these, never
# refuses — and per the note above, Warning MUST sit on the sh:property
# block itself or write.rs::is_blocking (severity == "Violation") never
# sees it and the write halts anyway).
fsh:SystemColorShape a sh:NodeShape ; sh:targetClass flow:System ;
  sh:property [ sh:path flow:color ; sh:pattern "^#[0-9a-fA-F]{3,6}$" ; sh:severity sh:Warning ] .
fsh:RequirementDateShape a sh:NodeShape ; sh:targetClass flow:Requirement ;
  sh:property [ sh:path flow:startDate ; sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" ; sh:severity sh:Violation ] ;
  sh:property [ sh:path flow:dueDate ; sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" ; sh:severity sh:Violation ] .
fsh:RequirementDurationShape a sh:NodeShape ; sh:targetClass flow:Requirement ;
  sh:property [ sh:path flow:durationDays ; sh:minInclusive 1 ; sh:severity sh:Warning ] .
fsh:TaskDateShape a sh:NodeShape ; sh:targetClass flow:Task ;
  sh:property [ sh:path flow:startDate ; sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" ; sh:severity sh:Violation ] ;
  sh:property [ sh:path flow:dueDate ; sh:pattern "^[0-9]{4}-[0-9]{2}-[0-9]{2}$" ; sh:severity sh:Violation ] .
fsh:TaskDurationShape a sh:NodeShape ; sh:targetClass flow:Task ;
  sh:property [ sh:path flow:durationDays ; sh:minInclusive 1 ; sh:severity sh:Warning ] .

# ---- sh:or class-typing on uri (object) predicates — NOT derivable from
# {datatype:uri} alone, which only yields sh:nodeKind sh:IRI
fsh:SystemParentTypeShape a sh:NodeShape ; sh:targetClass flow:System ;
  sh:property [ sh:path flow:parent ; sh:class flow:System ; sh:severity sh:Violation ] .
fsh:RequirementOwnedByTypeShape a sh:NodeShape ; sh:targetClass flow:Requirement ;
  sh:property [ sh:path flow:ownedBy ; sh:or ( [ sh:class flow:System ] [ sh:class flow:Constraint ] [ sh:class flow:Trade ] ) ; sh:severity sh:Violation ] .
fsh:TaskOwnedByTypeShape a sh:NodeShape ; sh:targetClass flow:Task ;
  sh:property [ sh:path flow:ownedBy ; sh:or ( [ sh:class flow:System ] [ sh:class flow:Workflow ] ) ; sh:severity sh:Violation ] .
fsh:OutcomeWorkflowTypeShape a sh:NodeShape ; sh:targetClass flow:Outcome ;
  sh:property [ sh:path flow:workflow ; sh:class flow:Workflow ; sh:severity sh:Violation ] .
fsh:WorkflowLinkTypeShape a sh:NodeShape ; sh:targetClass flow:WorkflowLink ;
  sh:property [ sh:path flow:workflow ; sh:class flow:Workflow ; sh:severity sh:Violation ] ;
  sh:property [ sh:path flow:system ; sh:class flow:System ; sh:severity sh:Violation ] .
fsh:TradeWinnerTypeShape a sh:NodeShape ; sh:targetClass flow:Trade ;
  sh:property [ sh:path flow:winner ; sh:class flow:System ; sh:severity sh:Violation ] .
fsh:TradeLinkTypeShape a sh:NodeShape ; sh:targetClass flow:TradeLink ;
  sh:property [ sh:path flow:trade ; sh:class flow:Trade ; sh:severity sh:Violation ] ;
  sh:property [ sh:path flow:system ; sh:class flow:System ; sh:severity sh:Violation ] .
fsh:ConstraintLinkTypeShape a sh:NodeShape ; sh:targetClass flow:ConstraintLink ;
  sh:property [ sh:path flow:constraint ; sh:class flow:Constraint ; sh:severity sh:Violation ] ;
  sh:property [ sh:path flow:target ; sh:or ( [ sh:class flow:System ] [ sh:class flow:Requirement ] ) ; sh:severity sh:Violation ] .
fsh:SourceOwnedByTypeShape a sh:NodeShape ; sh:targetClass flow:Source ;
  sh:property [ sh:path flow:ownedBy ; sh:or ( [ sh:class flow:System ] [ sh:class flow:Workflow ] [ sh:class flow:Constraint ] [ sh:class flow:Trade ] ) ; sh:severity sh:Violation ] .
fsh:EdgeTypeShape a sh:NodeShape ; sh:targetClass flow:Edge ;
  sh:property [ sh:path flow:sourceNode ; sh:or ( [ sh:class flow:System ] [ sh:class flow:Workflow ] [ sh:class flow:Trade ] [ sh:class flow:Constraint ] ) ; sh:severity sh:Violation ] ;
  sh:property [ sh:path flow:targetNode ; sh:or ( [ sh:class flow:System ] [ sh:class flow:Workflow ] [ sh:class flow:Trade ] [ sh:class flow:Constraint ] [ sh:class flow:Requirement ] ) ; sh:severity sh:Violation ] .
fsh:DependencyTypeShape a sh:NodeShape ; sh:targetClass flow:Dependency ;
  sh:property [ sh:path flow:predecessor ; sh:or ( [ sh:class flow:Task ] [ sh:class flow:Requirement ] ) ; sh:severity sh:Violation ] ;
  sh:property [ sh:path flow:successor ; sh:or ( [ sh:class flow:Task ] [ sh:class flow:Requirement ] ) ; sh:severity sh:Violation ] .

# ---- FLOW-RTRIP-11 #4: flow:ownedBy gains rdfs:domain/rdfs:range, correctly
# as an owl:unionOf (a bare rdfs:domain/rdfs:range per triple is AND-semantics
# under RDFS entailment — asserting it three times would wrongly entail every
# owner is simultaneously a Requirement AND a Task AND a Source. The real
# per-owner-kind constraint is the sh:or shapes above; this axiom is
# documentary, RDFS-sound, and inert to the SHACL validator (it targets no
# sh:NodeShape).
flow:ownedBy a rdf:Property ;
  flow:columnOf "requirements.system_id | tasks.owner_id | sources.owner_id" ;
  rdfs:domain [ a owl:Class ; owl:unionOf ( flow:Requirement flow:Task flow:Source ) ] ;
  rdfs:range  [ a owl:Class ; owl:unionOf ( flow:System flow:Constraint flow:Trade flow:Workflow ) ] .

# columnOf documentary triples for the RTRIP-11 renames (##1-3), so the
# provenance back to the DDL survives the rename.
flow:requirementSource a rdf:Property ; flow:columnOf "requirements.source" ;
  rdfs:comment "RENAMED from flow:source (RTRIP-11 #1): flow:source and flow:Source differed only by case." .
flow:sourceCitation a rdf:Property ; flow:columnOf "sources.text" ;
  rdfs:comment "RENAMED from flow:text (RTRIP-11 #2): flow:text also carries requirements.text | tasks.text | outcomes.text, a different kind of field (a statement, not a citation)." .
flow:tradeRationale a rdf:Property ; flow:columnOf "trades.description" ;
  rdfs:comment "RENAMED from flow:description (RTRIP-11 #3): trades.description is a decision rationale (types.ts:79), not a plain description, and FLOW-ATTR-1 attributes it by name." .

# ---- sh:sparql invariants, ported from courtship/flow-shapes-v1.ttl verbatim
# (SELECT bodies unchanged — none reference a renamed predicate)
fsh:SystemParentCycleShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:System ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "a system's parent chain reaches itself (hierarchy.ts validParents forbids this; bfsOrder would orphan it)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:parent>+ $this }""" ] .
# fsh:SystemGroupDimsWarning (flow-shapes-v1.ttl) is deliberately NOT ported:
# it checks a group's absence of explicit width/height, but width/height are
# scene geometry excluded from :projection:flow entirely (interfaces.md §C) —
# the check is unanswerable at the resource layer (every group would
# trivially satisfy FILTER NOT EXISTS since width/height never appear in this
# projection at all), so porting it verbatim would make it a permanently-
# vacuous, always-fires Warning. FLOW-GARDEN-P3's effectiveExtent() (contracts/
# garden.md §4) is where group-sizing is actually answered, post-partition.
fsh:TaskOwnerTypeMismatchShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:Task ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "owner_type disagrees with the owner's class (store filters tasks by owner_type AND owner_id — useModelStore.ts:353, 402)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:ownerType> ?t ; <urn:sophia:flow:vocab:ownedBy> ?o . ?o a ?c . FILTER( (?t = "system" && ?c != <urn:sophia:flow:vocab:System>) || (?t = "workflow" && ?c != <urn:sophia:flow:vocab:Workflow>) ) }""" ] .
fsh:WorkflowLinkDuplicateShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:WorkflowLink ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "duplicate workflow<->system link (addWorkflowLink de-duplicates, useModelStore.ts:493)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:workflow> ?w ; <urn:sophia:flow:vocab:system> ?s . ?other a <urn:sophia:flow:vocab:WorkflowLink> ; <urn:sophia:flow:vocab:workflow> ?w ; <urn:sophia:flow:vocab:system> ?s . FILTER(?other != $this) }""" ] .
fsh:TradeWinnerNotCandidateShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:Trade ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "the winner is not a linked candidate (removeTradeLink clears the winner; detachSystemsFromTrades nulls it; the UI only offers linked candidates - useModelStore.ts:561-578, repo.ts:477-482, DetailsPanel.tsx:81-92)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:winner> ?w . FILTER NOT EXISTS { ?l a <urn:sophia:flow:vocab:TradeLink> ; <urn:sophia:flow:vocab:trade> $this ; <urn:sophia:flow:vocab:system> ?w } }""" ] .
fsh:TradeLinkDuplicateShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:TradeLink ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "duplicate trade<->candidate link (addTradeLink de-duplicates, useModelStore.ts:555)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:trade> ?t ; <urn:sophia:flow:vocab:system> ?s . ?other a <urn:sophia:flow:vocab:TradeLink> ; <urn:sophia:flow:vocab:trade> ?t ; <urn:sophia:flow:vocab:system> ?s . FILTER(?other != $this) }""" ] .
fsh:ConstraintLinkDuplicateShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:ConstraintLink ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "duplicate constraint->target link (addConstraintLink de-duplicates, useModelStore.ts:624)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:constraint> ?c ; <urn:sophia:flow:vocab:target> ?t . ?other a <urn:sophia:flow:vocab:ConstraintLink> ; <urn:sophia:flow:vocab:constraint> ?c ; <urn:sophia:flow:vocab:target> ?t . FILTER(?other != $this) }""" ] .
fsh:EdgeSelfLoopShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:Edge ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "self-loop (onConnect refuses source === target, Canvas.tsx)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:sourceNode> ?n ; <urn:sophia:flow:vocab:targetNode> ?n }""" ] .
fsh:EdgeDuplicateShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:Edge ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "duplicate free edge (addFreeEdge de-duplicates, useModelStore.ts:660)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:sourceNode> ?a ; <urn:sophia:flow:vocab:targetNode> ?b . ?other a <urn:sophia:flow:vocab:Edge> ; <urn:sophia:flow:vocab:sourceNode> ?a ; <urn:sophia:flow:vocab:targetNode> ?b . FILTER(?other != $this) }""" ] .
fsh:DependencySelfShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:Dependency ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "self-dependency (wouldCreateCycle returns true for pred === succ, schedule.ts:123)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:predecessor> ?p ; <urn:sophia:flow:vocab:successor> ?p }""" ] .
fsh:DependencyCycleShape a sh:NodeShape ; sh:severity sh:Warning ; sh:targetClass flow:Dependency ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Warning ;
    sh:message "dependency cycle (refused at entry by wouldCreateCycle; computeSchedule only warns and schedules anyway, schedule.ts:92-96)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:predecessor> ?p ; <urn:sophia:flow:vocab:successor> ?s . ?s (^<urn:sophia:flow:vocab:predecessor>/<urn:sophia:flow:vocab:successor>)+ ?p }""" ] .
fsh:DependencyDuplicateShape a sh:NodeShape ; sh:severity sh:Violation ; sh:targetClass flow:Dependency ;
  sh:sparql [ a sh:SPARQLConstraint ;
    sh:severity sh:Violation ;
    sh:message "duplicate dependency (addDep de-duplicates, useModelStore.ts:673)" ;
    sh:select """SELECT $this WHERE { $this <urn:sophia:flow:vocab:predecessor> ?p ; <urn:sophia:flow:vocab:successor> ?s . ?other a <urn:sophia:flow:vocab:Dependency> ; <urn:sophia:flow:vocab:predecessor> ?p ; <urn:sophia:flow:vocab:successor> ?s . FILTER(?other != $this) }""" ] .
